import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"正宫·醉太平湖上","description":"","frontmatter":{"title":"正宫·醉太平湖上","date":"2026-11-11T00:00:00.000Z","seq":22,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/正宫·醉太平湖上.md","filePath":"blogs/元曲·张可久/正宫·醉太平湖上.md"}'),p={name:"blogs/元曲·张可久/正宫·醉太平湖上.md"};function _(c,a,l,n,r,m){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="正宫·醉太平湖上" tabindex="-1">正宫·醉太平湖上 <a class="header-anchor" href="#正宫·醉太平湖上" aria-label="Permalink to &quot;正宫·醉太平湖上&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">洗荷花过雨，浴明月平湖，暮云楼观景模糊。</p><p class="poem-stanza">兰舟棹举，溯凉波似泛银河去，对清风不放金杯住，上雕鞍谁记玉人扶？听新声乐府。</p><p class="poem-stanza">无题尘蒙了镜台，粉淡了香腮，不提防今夜故人来。</p><p class="poem-stanza">你将我左猜，小冤家怕不道心儿里爱，老妖精拘管的人来煞，村冯魁割舍得柱儿颏，远乡了秀才。</p><p class="poem-stanza">人皆嫌命窘，谁不见钱亲？水晶环入面糊盆，才沾粘便滚。</p><p class="poem-stanza">文章糊了盛钱囤，门庭改做迷魂阵，清廉贬入睡馄饨，胡芦提倒稳。</p><p class="poem-stanza">陶朱公钓船，晋处士田园，潜居水陆脱尘缘，比别人虑远。</p><p class="poem-stanza">贤愚参杂随时变，醉醒和哄迷歌宴，清浊混沌待残年，休呆波屈原！。</p></div>',3)])])}const u=s(p,[["render",_]]);export{d as __pageData,u as default};
